harnessSource:
// syzygy-bpyt.8.9 differential harness: runs the adapter-credential probe over every fixture case and writes each outcome to
// $B89_OUT. The driver copies this file into packages/polaris-dossier/src/ and runs it once with the fix and once with the base
// subject files written over it. The base probe has no fourth parameter, so it ignores the declarations a case passes.
import * as fs from 'node:fs';
import { tmpdir } from 'node:os';
import * as path from 'node:path';
import { it } from 'vitest';
import { createCredentialProbe, credentialListFromEnv, type CredentialListSource, type OpenForRead } from './credential-probe.js';

type Declarations = readonly { readonly adapter: string; readonly credentials: readonly string[] }[];
type Probe4 = (source: CredentialListSource, open?: OpenForRead, configured?: readonly string[], adapters?: Declarations) => ReturnType<typeof createCredentialProbe>;

const SOURCES: Record<string, () => CredentialListSource> = {
  unset: () => credentialListFromEnv({}),
  empty: () => ({ describe: 'fixture list', list: () => ({ ok: true, paths: [] }) }),
  'lists-absent': () => ({ describe: 'fixture list', list: () => ({ ok: true, paths: ['/f/listed-absent.token'] }) }),
  'lists-readable': () => ({ describe: 'fixture list', list: () => ({ ok: true, paths: ['/f/listed-readable.token'] }) }),
  'lists-undecidable': () => ({ describe: 'fixture list', list: () => ({ ok: true, paths: ['/f/listed-eio.token'] }) }),
  'lists-the-declared-path': () => ({ describe: 'fixture list', list: () => ({ ok: true, paths: ['/f/declared-unlisted.token'] }) }),
  malformed: () => ({ describe: 'fixture list', list: () => ({ ok: false, why: 'fixture list is malformed' }) }),
};
const CONFIGURED: Record<string, readonly string[]> = {
  none: [],
  absent: ['/f/configured-absent.token'],
  readable: ['/f/configured-readable.token'],
};
const ADAPTERS: Record<string, ((configured: readonly string[]) => Declarations) | null> = {
  omitted: null,
  none: () => [],
  'declares-nothing': () => [{ adapter: 'fx-a', credentials: [] }],
  'declares-the-configured-paths': (configured) => [{ adapter: 'fx-a', credentials: [...configured] }],
  'declares-an-unlisted-path': () => [{ adapter: 'fx-a', credentials: ['/f/declared-unlisted.token'] }],
  'two-adapters-mixed': (configured) => [{ adapter: 'fx-a', credentials: [...configured, '/f/declared-unlisted.token'] }, { adapter: 'fx-b', credentials: ['/f/declared-unlisted-2.token'] }],
  'declares-a-respelled-path': () => [{ adapter: 'fx-a', credentials: ['/f//configured-absent.token'] }],
};

const injectedOpen = (opens: string[]): OpenForRead => (file) => {
  opens.push(file);
  if (file.includes('readable')) return { opened: true, regularFile: true };
  if (file.includes('eio')) return { opened: false, code: 'EIO' };
  return { opened: false, code: 'ENOENT' };
};

async function fixtureCase(sourceId: string, configuredId: string, adaptersId: string) {
  let reads = 0;
  const inner = SOURCES[sourceId]!();
  const source: CredentialListSource = { describe: inner.describe, list: () => { reads += 1; return inner.list(); } };
  const opens: string[] = [];
  const configured = CONFIGURED[configuredId]!;
  const declarations = ADAPTERS[adaptersId];
  const create = createCredentialProbe as Probe4;
  const probe = declarations === null ? create(source, injectedOpen(opens), configured) : create(source, injectedOpen(opens), configured, declarations(configured));
  const result = await probe.probe();
  return { case: `${sourceId} / configured ${configuredId} / adapters ${adaptersId}`, declarations: declarations === null ? 'omitted' : declarations(configured), result, last: probe.last(), listReads: reads, opens };
}

// The CLI's own call shape, `createCredentialProbe(credentialListFromEnv(env))`, with the real operating-system open over real files.
async function cliCase(name: string, write: ((dir: string) => string) | null) {
  const dir = fs.realpathSync(fs.mkdtempSync(path.join(tmpdir(), 'b89-diff-')));
  try {
    const env = write === null ? {} : { SYZYGY_DOSSIER_CREDENTIAL_LIST: write(dir) };
    const probe = createCredentialProbe(credentialListFromEnv(env));
    const scrub = (value: unknown) => JSON.parse(JSON.stringify(value).split(dir).join('<dir>'));
    return { case: `cli shape / ${name}`, declarations: 'omitted', result: scrub(await probe.probe()), last: scrub(probe.last()), listReads: null, opens: null };
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
}

const listFile = (dir: string, credentials: unknown): string => {
  const file = path.join(dir, 'credentials.json');
  fs.writeFileSync(file, JSON.stringify({ format: 'syzygy-adapter-credential-list/1', credentials }));
  return file;
};

it('writes every case outcome', async () => {
  const rows = [];
  for (const sourceId of Object.keys(SOURCES)) {
    for (const configuredId of Object.keys(CONFIGURED)) {
      for (const adaptersId of Object.keys(ADAPTERS)) rows.push(await fixtureCase(sourceId, configuredId, adaptersId));
    }
  }
  rows.push(await cliCase('no list named', null));
  rows.push(await cliCase('empty list file', (dir) => listFile(dir, [])));
  rows.push(await cliCase('list file naming an absent path', (dir) => listFile(dir, [path.join(dir, 'absent.token')])));
  rows.push(await cliCase('list file naming a readable file', (dir) => { fs.writeFileSync(path.join(dir, 'p.token'), 'secret', { mode: 0o600 }); return listFile(dir, [path.join(dir, 'p.token')]); }));
  rows.push(await cliCase('list file naming a directory', (dir) => { fs.mkdirSync(path.join(dir, 'd')); return listFile(dir, [path.join(dir, 'd')]); }));
  rows.push(await cliCase('malformed list file', (dir) => { fs.writeFileSync(path.join(dir, 'credentials.json'), '{not json'); return path.join(dir, 'credentials.json'); }));
  rows.push(await cliCase('missing list file', (dir) => path.join(dir, 'missing.json')));
  fs.writeFileSync(process.env['B89_OUT']!, `${JSON.stringify(rows, null, 2)}\n`);
});
